import{c as a,Z as n,Q as r,j as s,m as o,o as i}from"./chunks/framework.g_l1frA7.js";const f=JSON.parse('{"title":"Configuring AI","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/configuring-ai.md","filePath":"getting-started/configuring-ai.md","lastUpdated":null}'),l={name:"getting-started/configuring-ai.md"};function d(c,e,h,u,g,p){const t=n("ProviderCard");return r(),s("div",null,[e[0]||(e[0]=o('<h1 id="configuring-ai" tabindex="-1">Configuring AI <a class="header-anchor" href="#configuring-ai" aria-label="Permalink to &quot;Configuring AI&quot;">​</a></h1><p>AI in FinSight is <strong>opt-in and per-user</strong>. Two features use it: auto-categorization and the Copilot. Everything else — ledger, budgets, goals, reports — is deterministic finance math in <code>finsight-core</code>.</p><p>Without a provider, FinSight still works: categorization falls back to rules + deterministic heuristics, and the Copilot simply does not run.</p><h2 id="providers" tabindex="-1">Providers <a class="header-anchor" href="#providers" aria-label="Permalink to &quot;Providers&quot;">​</a></h2><p>Configure a provider at <strong>Settings → Agent</strong>. The key is stored inside your encrypted per-user database, not a process-global keychain.</p>',5)),i(t,{title:"Ollama",subtitle:"Local inference — stays on your hardware",icon:"cpu",badge:"Private",description:"Run a local model (e.g. Qwen, Llama) via the Ollama HTTP API. FinSight sends the same context it would to a cloud provider, but the bytes never leave your network.",bullets:["No data leaves your machine","Good for categorization and Copilot Q&A","Configure base URL (default http://ollama:11434)"]}),i(t,{title:"OpenAI-Compatible",subtitle:"Any OpenAI API + compatible gateways",icon:"box",description:"Works with OpenAI, Azure OpenAI, and self-hosted OpenAI-compatible endpoints (e.g. vLLM, LocalAI). FinSight’s CompletionProvider trait abstracts the HTTP layer.",bullets:["Set base URL, model, and API key","Use any compatible gateway you operate"]}),i(t,{title:"Anthropic",subtitle:"Claude models via the Anthropic API",icon:"brain",description:"Native Anthropic provider for Claude models. Useful when you already have an Anthropic key and want their models for Copilot reasoning.",bullets:["Set model and API key in Settings → Agent","Same context controls as other providers"]}),e[1]||(e[1]=o('<h2 id="what-is-sent" tabindex="-1">What is sent <a class="header-anchor" href="#what-is-sent" aria-label="Permalink to &quot;What is sent&quot;">​</a></h2><ul><li><strong>Auto-categorization (batch):</strong> the redacted merchant description and amount of <em>uncategorized</em> transactions only — enough to classify, not your whole ledger.</li><li><strong>Copilot:</strong> the relevant financial context for the question — cashflow, budget, goals, transactions in scope, plus stored memories — assembled in <code>finsight-agent::context::build_context</code>. See <a href="/FinSight/copilot/privacy">Copilot → Privacy</a>.</li></ul><p>Settings → Agent explains the flow before you save. You can change or remove the provider at any time; existing ledger data is untouched.</p><h2 id="can-i-use-finsight-without-cloud-ai" tabindex="-1">Can I use FinSight without cloud AI? <a class="header-anchor" href="#can-i-use-finsight-without-cloud-ai" aria-label="Permalink to &quot;Can I use FinSight without cloud AI?&quot;">​</a></h2><p>Yes. Categories can be set manually, rules handle repetition, and Reports/Scenarios are deterministic. Add a provider later and both categorization and Copilot light up with no migration.</p><h2 id="verifying-your-setup" tabindex="-1">Verifying your setup <a class="header-anchor" href="#verifying-your-setup" aria-label="Permalink to &quot;Verifying your setup&quot;">​</a></h2><ol><li>Save the provider in Settings → Agent.</li><li>Look for the agent status indicator in the sidebar (last scan time).</li><li>Ask the Copilot a simple question (“How much did I spend on groceries last month?”) — the Composer streams the response via SSE.</li></ol><p>If streaming fails, check the server logs (<code>docker compose logs -f finsight</code>) and that <code>FINSIGHT_PUBLIC_ORIGIN</code> matches your external HTTPS origin when behind a proxy.</p><p>Next: <a href="/FinSight/getting-started/privacy">Privacy &amp; Local Data</a>.</p>',9))])}const y=a(l,[["render",d]]);export{f as __pageData,y as default};
